export function HeaderElement({
  brand = "{{brand}}",
  scope = "{{scope}}",
  accent = "{{accent}}",
  showNav = {{showNav}},
}) {
  return (
    <div style={{ width: 380, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif" }}>
      <p style={{ margin: "0 0 8px", fontSize: 12, color: "#241430888" }}>Scope: <strong>{`<${scope}>`}</strong> header</p>
      <header style={{ display: "flex", alignItems: "center", justifyContent: "space-between", background: "#FAF7F2", padding: "14px 18px", borderBottom: `3px solid ${accent}`, borderRadius: "10px 10px 0 0" }}>
        <span style={{ fontWeight: 800, fontSize: 16, color: accent }}>{brand}</span>
        {showNav && (
          <nav style={{ display: "flex", gap: 16 }}>
            <a href="#" style={{ color: "#241430", textDecoration: "none", fontWeight: 600, fontSize: 13 }}>Work</a>
            <a href="#" style={{ color: "#241430", textDecoration: "none", fontWeight: 600, fontSize: 13 }}>About</a>
            <a href="#" style={{ color: "#241430", textDecoration: "none", fontWeight: 600, fontSize: 13 }}>Contact</a>
          </nav>
        )}
      </header>
    </div>
  );
}
